import React, {Fragment, useEffect, useMemo, useState} from 'react';
import Link from '@docusaurus/Link';

import SiteLink from '@site/src/components/SiteLink';
import data from '../data/glossary.json';

// The data is generated by scripts/sync-glossary.mjs from the public Google Sheet and
// committed, so this page never talks to Google at runtime. See /glossary for the page.
const TERMS = data.terms;
const SITE = 'https://dhamma.gift';

// Same normalisation as scripts/lib/glossary.mjs: NFD + strip combining marks, so
// «tanha» finds «taṇhā», and «ё» finds «е». Duplicated because scripts/ is not bundled.
function normalize(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/\p{M}+/gu, '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[’'`]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const COLLATORS = {
  en: new Intl.Collator('en', {sensitivity: 'base', numeric: true}),
  ru: new Intl.Collator('ru', {sensitivity: 'base', numeric: true}),
};

const STRINGS = {
  ru: {
    search: 'Поиск по пали или переводу',
    searchLabel: 'Поиск по глоссарию',
    clearSearch: 'Очистить поиск',
    all: 'Все',
    alphabetLabel: 'Указатель по пали',
    canonOnly: 'Только с определением из канона',
    found: (n, total) => `Найдено ${n} из ${total}`,
    reset: 'Сбросить',
    empty: 'Ничего не найдено',
    emptyHint: 'Попробуйте другой запрос или сбросьте фильтры.',
    tableCaption: 'Глоссарий перевода: пали, русский перевод и определения из канона',
    colPali: 'Пали',
    colTranslation: 'Русский',
    details: 'Подробнее',
    close: 'Свернуть',
    canonDefinition: 'Определение из канона',
    openReader: 'Открыть в ридере',
    refs: 'Ссылки',
    where: 'Где канон определяет',
    compounds: 'Составные с определением',
    patterns: 'По шаблонам finddhamma',
    broader: 'Шире',
    vinaya: 'Виная (Вибханги)',
    dgNote: 'Пояснение DG',
    rationale: 'Обоснование',
    copyLink: 'Ссылка',
    copied: 'Скопировано',
    exportCsv: 'CSV',
    exportMd: 'MD',
    exportHint: 'Экспорт отфильтрованного списка',
    more: (n) => `ещё ${n}`,
    updated: 'Обновлено',
    source: 'Рабочая таблица (Google Sheet)',
  },
  en: {
    search: 'Search Pali or translation',
    searchLabel: 'Search the glossary',
    clearSearch: 'Clear search',
    all: 'All',
    alphabetLabel: 'Pali index',
    canonOnly: 'Only with a canon definition',
    found: (n, total) => `Found ${n} of ${total}`,
    reset: 'Reset',
    empty: 'Nothing found',
    emptyHint: 'Try another query or reset the filters.',
    tableCaption: 'Translation glossary: Pali, English rendering and canon definitions',
    colPali: 'Pali',
    colTranslation: 'English',
    details: 'Details',
    close: 'Collapse',
    canonDefinition: 'Canon definition',
    openReader: 'Open in the reader',
    refs: 'References',
    where: 'Where the canon defines it',
    compounds: 'Compounds with a definition',
    patterns: 'By finddhamma patterns',
    broader: 'Broader',
    vinaya: 'Vinaya (Vibhaṅgas)',
    dgNote: 'DG note',
    rationale: 'Rationale',
    copyLink: 'Link',
    copied: 'Copied',
    exportCsv: 'CSV',
    exportMd: 'MD',
    exportHint: 'Export the filtered list',
    more: (n) => `+${n} more`,
    updated: 'Updated',
    source: 'Working table (Google Sheet)',
  },
};

function isExternal(value) {
  return /^https?:\/\//i.test(value);
}

function withLang(link, locale) {
  if (!link) return '';
  if (isExternal(link)) return link;
  return `${link}${link.includes('?') ? '&' : '?'}lang=${locale}`;
}

function linkLabel(link) {
  return String(link).replace(/^https?:\/\/[^/]+/i, '').replace(/^\//, '');
}

function absoluteLink(link, locale) {
  if (!link) return '';
  const withLocale = withLang(link, locale);
  if (isExternal(withLocale)) return withLocale;
  const origin = typeof window === 'undefined' ? SITE : window.location.origin;
  return `${origin}${withLocale}`;
}

// Sutta/Vinaya ids only. «(+15)», «…» and anything unexpected stay plain text, so a typo in
// the sheet cannot turn into a broken app link.
const REF_ID = /^(?:[a-z]{1,4}\d[\w.:-]*|pli-tv-[\w-]+)$/i;

function hasDetails(term, locale) {
  const canon = term.canon || {};
  return Boolean(
    canon.definition ||
      canon.link ||
      canon.where?.length ||
      canon.compounds?.length ||
      canon.patterns?.length ||
      canon.broader?.length ||
      canon.vinaya?.length ||
      term.rationale ||
      (locale === 'ru' && term.dgNote),
  );
}

function CanonLink({link, locale, t}) {
  const label = `${t.openReader} · ${linkLabel(link)} →`;
  if (isExternal(link)) {
    return (
      <a href={link} target="_blank" rel="noopener noreferrer">
        {label}
      </a>
    );
  }
  if (!link.startsWith('/')) return <span>{link}</span>;
  return <SiteLink to={withLang(link, locale)}>{label}</SiteLink>;
}

function RefChip({value, locale, t}) {
  const more = value.match(/^\(\+(\d+)\)$/);
  if (more) return <span className="dg-glossary__more">{t.more(Number(more[1]))}</span>;
  if (!REF_ID.test(value)) return <span className="dg-glossary__chip dg-glossary__chip--text">{value}</span>;
  return (
    <SiteLink className="dg-glossary__chip" to={withLang(`/${value}`, locale)}>
      {value}
    </SiteLink>
  );
}

function TermDetails({term, t, locale, copied, onCopy}) {
  const canon = term.canon || {};
  const groups = [
    ['where', t.where, canon.where],
    ['compounds', t.compounds, canon.compounds],
    ['patterns', t.patterns, canon.patterns],
    ['broader', t.broader, canon.broader],
    ['vinaya', t.vinaya, canon.vinaya],
  ].filter(([, , refs]) => refs && refs.length);
  const rationale = term.rationale?.[locale];

  return (
    <tr className="dg-glossary__details" id={`details-${term.id}`}>
      <td colSpan={2}>
        <div className="dg-glossary__details-inner">
          {canon.definition && (
            <section className="dg-glossary__section">
              <h4>{t.canonDefinition}</h4>
              <p className="dg-glossary__definition" lang="pi">
                {canon.definition}
              </p>
            </section>
          )}
          {canon.link && (
            <p className="dg-glossary__reader-link">
              <CanonLink link={canon.link} locale={locale} t={t} />
            </p>
          )}
          {groups.length > 0 && (
            <section className="dg-glossary__section">
              <h4>{t.refs}</h4>
              {groups.map(([key, label, refs]) => (
                <div key={key} className="dg-glossary__refgroup">
                  <span className="dg-glossary__reflabel">{label}</span>
                  <span className="dg-glossary__chips">
                    {refs.map((value, index) => (
                      <RefChip key={`${key}-${value}-${index}`} value={value} locale={locale} t={t} />
                    ))}
                  </span>
                </div>
              ))}
            </section>
          )}
          {locale === 'ru' && term.dgNote && (
            <section className="dg-glossary__section">
              <h4>{t.dgNote}</h4>
              <p className="dg-glossary__note">{term.dgNote}</p>
            </section>
          )}
          <div className="dg-glossary__meta">
            {term.num != null && <span className="dg-glossary__num">#{term.num}</span>}
            {rationale && (
              <Link className="dg-glossary__meta-link" to={rationale}>
                {t.rationale} →
              </Link>
            )}
            <button type="button" className="dg-glossary__copy" onClick={() => onCopy(term.id)}>
              {copied === term.id ? t.copied : t.copyLink}
            </button>
          </div>
        </div>
      </td>
    </tr>
  );
}

export default function GlossaryTable({locale = 'en'}) {
  const t = STRINGS[locale] || STRINGS.en;
  const collator = COLLATORS[locale] || COLLATORS.en;

  const [query, setQuery] = useState('');
  const [letter, setLetter] = useState('');
  const [canonOnly, setCanonOnly] = useState(false);
  const [sortKey, setSortKey] = useState('pali');
  const [sortDir, setSortDir] = useState('asc');
  const [open, setOpen] = useState(() => new Set());
  const [copied, setCopied] = useState('');
  const [highlight, setHighlight] = useState('');

  const letters = useMemo(() => {
    const set = new Set();
    for (const term of TERMS) {
      const first = normalize(term.pali)[0];
      if (first) set.add(first.toUpperCase());
    }
    return [...set].sort((a, b) => collator.compare(a, b));
  }, [collator]);

  const searchIndex = useMemo(
    () => new Map(TERMS.map((term) => [term.id, normalize(`${term.pali} ${locale === 'ru' ? term.ru : term.en}`)])),
    [locale],
  );

  const canonCount = useMemo(() => TERMS.filter((term) => term.canon?.definition).length, []);

  const filtered = useMemo(() => {
    const needle = normalize(query);
    return TERMS.filter((term) => {
      if (letter && (normalize(term.pali)[0] || '').toUpperCase() !== letter) return false;
      if (canonOnly && !term.canon?.definition) return false;
      if (needle && !searchIndex.get(term.id)?.includes(needle)) return false;
      return true;
    });
  }, [query, letter, canonOnly, searchIndex]);

  const sorted = useMemo(() => {
    const value = (term) => (sortKey === 'pali' ? term.pali : locale === 'ru' ? term.ru : term.en);
    return [...filtered].sort((a, b) => {
      const av = value(a);
      const bv = value(b);
      if (!av && !bv) return 0;
      if (!av) return 1;
      if (!bv) return -1;
      const result = collator.compare(normalize(av), normalize(bv));
      return sortDir === 'asc' ? result : -result;
    });
  }, [filtered, sortKey, sortDir, locale, collator]);

  const updated = useMemo(() => {
    if (!data.updatedAt) return '';
    const format = new Intl.DateTimeFormat(locale === 'ru' ? 'ru-RU' : 'en-GB', {
      dateStyle: 'long',
      timeZone: 'UTC',
    });
    return format.format(new Date(`${data.updatedAt}T00:00:00Z`));
  }, [locale]);

  useEffect(() => {
    function openFromHash() {
      let id = '';
      try {
        id = decodeURIComponent(window.location.hash.slice(1));
      } catch {
        return;
      }
      if (!id) return;
      if (!TERMS.some((term) => term.id === id)) return;
      setQuery('');
      setLetter('');
      setCanonOnly(false);
      setOpen((previous) => new Set(previous).add(id));
      setHighlight(id);
      window.setTimeout(() => setHighlight((current) => (current === id ? '' : current)), 2200);
      const reducedMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
      window.requestAnimationFrame(() => {
        document
          .getElementById(`term-${id}`)
          ?.scrollIntoView({block: 'center', behavior: reducedMotion ? 'auto' : 'smooth'});
      });
    }
    openFromHash();
    window.addEventListener('hashchange', openFromHash);
    return () => window.removeEventListener('hashchange', openFromHash);
  }, []);

  function changeSort(key) {
    if (sortKey === key) setSortDir((current) => (current === 'asc' ? 'desc' : 'asc'));
    else {
      setSortKey(key);
      setSortDir('asc');
    }
  }

  function reset() {
    setQuery('');
    setLetter('');
    setCanonOnly(false);
  }

  function toggle(id) {
    const isOpen = open.has(id);
    const next = new Set(open);
    if (isOpen) next.delete(id);
    else next.add(id);
    setOpen(next);
    if (typeof window === 'undefined') return;
    if (isOpen) {
      if (window.location.hash === `#${id}`) {
        window.history.replaceState(null, '', window.location.pathname + window.location.search);
      }
    } else {
      window.history.replaceState(null, '', `#${id}`);
    }
  }

  async function copyLink(id) {
    const url = `${window.location.origin}${window.location.pathname}#${id}`;
    try {
      await navigator.clipboard.writeText(url);
    } catch {
      const area = document.createElement('textarea');
      area.value = url;
      area.setAttribute('readonly', '');
      area.style.position = 'fixed';
      area.style.opacity = '0';
      document.body.appendChild(area);
      area.select();
      document.execCommand('copy');
      area.remove();
    }
    setCopied(id);
    window.setTimeout(() => setCopied((current) => (current === id ? '' : current)), 1600);
  }

  function exportRows() {
    return sorted.map((term) => [
      term.pali,
      locale === 'ru' ? term.ru : term.en,
      term.canon?.definition || '',
      absoluteLink(term.canon?.link, locale),
    ]);
  }

  function download(filename, text, type) {
    const blob = new Blob([text], {type});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  function downloadCsv() {
    const header = [t.colPali, t.colTranslation, t.canonDefinition, t.openReader];
    const rows = [header, ...exportRows()];
    const csv =
      '\uFEFF' +
      rows.map((row) => row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(',')).join('\r\n') +
      '\r\n';
    download(`glossary-${locale}.csv`, csv, 'text/csv;charset=utf-8');
  }

  function downloadMd() {
    const escape = (value) => String(value).replace(/\|/g, '\\|').replace(/\r?\n/g, '<br>');
    const header = [t.colPali, t.colTranslation, t.canonDefinition, t.openReader];
    const rows = exportRows().map((row) => `| ${row.map(escape).join(' | ')} |`);
    const md = `| ${header.map(escape).join(' | ')} |\n| --- | --- | --- | --- |\n${rows.join('\n')}\n`;
    download(`glossary-${locale}.md`, md, 'text/markdown;charset=utf-8');
  }

  const paliSort = sortKey === 'pali' ? (sortDir === 'asc' ? 'ascending' : 'descending') : 'none';
  const translationSort =
    sortKey === 'translation' ? (sortDir === 'asc' ? 'ascending' : 'descending') : 'none';
  const hasFilter = Boolean(query || letter || canonOnly);

  return (
    <div className="dg-glossary">
      <div className="dg-glossary__toolbar">
        <div className="dg-glossary__search">
          <input
            type="search"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder={t.search}
            aria-label={t.searchLabel}
            autoComplete="off"
            spellCheck="false"
          />
          {query && (
            <button
              type="button"
              className="dg-glossary__clear"
              onClick={() => setQuery('')}
              aria-label={t.clearSearch}
            >
              ×
            </button>
          )}
        </div>
        <label className="dg-glossary__check">
          <input type="checkbox" checked={canonOnly} onChange={(event) => setCanonOnly(event.target.checked)} />
          <span>
            {t.canonOnly} ({canonCount})
          </span>
        </label>
        <div className="dg-glossary__export">
          <button type="button" onClick={downloadCsv} title={t.exportHint}>
            {t.exportCsv}
          </button>
          <button type="button" onClick={downloadMd} title={t.exportHint}>
            {t.exportMd}
          </button>
        </div>
      </div>

      <div className="dg-glossary__letters" role="group" aria-label={t.alphabetLabel}>
        <button type="button" className={!letter ? 'is-active' : undefined} aria-pressed={!letter} onClick={() => setLetter('')}>
          {t.all}
        </button>
        {letters.map((value) => (
          <button
            key={value}
            type="button"
            className={letter === value ? 'is-active' : undefined}
            aria-pressed={letter === value}
            onClick={() => setLetter(letter === value ? '' : value)}
          >
            {value}
          </button>
        ))}
      </div>

      <div className="dg-glossary__status">
        <span aria-live="polite">{t.found(sorted.length, TERMS.length)}</span>
        {hasFilter && (
          <button type="button" className="dg-glossary__reset" onClick={reset}>
            {t.reset}
          </button>
        )}
      </div>

      {sorted.length === 0 ? (
        <div className="dg-glossary__empty">
          <p>{t.empty}</p>
          <p>{t.emptyHint}</p>
          <button type="button" onClick={reset}>
            {t.reset}
          </button>
        </div>
      ) : (
        <table className="dg-glossary__table">
          <caption className="dg-glossary__sr">{t.tableCaption}</caption>
          <thead>
            <tr>
              <th scope="col" aria-sort={paliSort} className="dg-glossary__col-pali">
                <button type="button" onClick={() => changeSort('pali')}>
                  {t.colPali}
                  {sortKey === 'pali' && <span aria-hidden="true"> {sortDir === 'asc' ? '↑' : '↓'}</span>}
                </button>
              </th>
              <th scope="col" aria-sort={translationSort}>
                <button type="button" onClick={() => changeSort('translation')}>
                  {t.colTranslation}
                  {sortKey === 'translation' && <span aria-hidden="true"> {sortDir === 'asc' ? '↑' : '↓'}</span>}
                </button>
              </th>
            </tr>
          </thead>
          <tbody>
            {sorted.map((term) => {
              const expandable = hasDetails(term, locale);
              const isOpen = open.has(term.id);
              return (
                <Fragment key={term.id}>
                  <tr id={`term-${term.id}`} className={highlight === term.id ? 'is-target' : undefined}>
                    <td className="dg-glossary__pali" lang="pi">
                      {term.pali}
                    </td>
                    <td className="dg-glossary__translation">
                      <div className="dg-glossary__translation-inner">
                        <span>{locale === 'ru' ? term.ru : term.en}</span>
                        {expandable && (
                          <button
                            type="button"
                            className="dg-glossary__toggle"
                            aria-expanded={isOpen}
                            aria-controls={`details-${term.id}`}
                            aria-label={`${isOpen ? t.close : t.details}: ${term.pali}`}
                            onClick={() => toggle(term.id)}
                          >
                            <span aria-hidden="true">{isOpen ? '−' : '+'}</span>
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                  {expandable && isOpen && (
                    <TermDetails term={term} t={t} locale={locale} copied={copied} onCopy={copyLink} />
                  )}
                </Fragment>
              );
            })}
          </tbody>
        </table>
      )}

      <p className="dg-glossary__source">
        {updated && (
          <>
            <span>
              {t.updated}: {updated}
            </span>
            {' · '}
          </>
        )}
        <a href={data.source.url} target="_blank" rel="noopener noreferrer">
          {t.source}
        </a>
      </p>
    </div>
  );
}
